// Seleziona le prenotazioni di DOMANI e prepara un promemoria per ciascuna.
// Gira una volta al giorno (18:00): ogni appuntamento cade in un solo giro,
// quindi niente doppi invii senza bisogno di segnare le righe.
const TZ = 'Europe/Rome';
const domani = DateTime.now().setZone(TZ).plus({ days: 1 }).toFormat('yyyy-LL-dd');

const righe = $input.all().map(i => i.json).filter(r => r && r.inizio);
const TEMPLATE = $env.META_TEMPLATE_PROMEMORIA;
const out = [];

for (const r of righe) {
  const stato = String(r.stato || '').toLowerCase();
  if (stato === 'annullata' || stato === 'disdetta') continue;

  let dt;
  try { dt = DateTime.fromISO(String(r.inizio), { zone: TZ }); } catch (e) { continue; }
  if (!dt.isValid || dt.toFormat('yyyy-LL-dd') !== domani) continue;

  const nome = String(r.nome || '').split(' ')[0] || '';
  const tipo = r.tipo || 'appuntamento';
  const ora = dt.setLocale('it').toFormat('HH:mm');

  let payload;
  if (TEMPLATE) {
    // Template approvato: unico modo per scrivere oltre le 24 ore
    payload = { type: 'template', template: {
      name: TEMPLATE, language: { code: 'it' },
      components: [{ type: 'body', parameters: [
        { type: 'text', text: nome || 'cliente' },
        { type: 'text', text: String(tipo) },
        { type: 'text', text: 'alle ' + ora },
      ]}],
    }};
  } else {
    // Fallback testo (arriva solo entro 24h dall'ultimo messaggio del cliente)
    payload = { type: 'text', text: {
      body: 'Ciao' + (nome ? ' ' + nome : '') + ' 👋 promemoria: ' + tipo +
            ' domani alle ' + ora + ' in ArilùFarma. A presto!',
      preview_url: false,
    }};
  }

  out.push({ json: { to: String(r.wa_id), payload } });
}

return out;
